PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS batch_items;DROP TABLE IF EXISTS reimbursement_batches;DROP TABLE IF EXISTS notifications;DROP TABLE IF EXISTS report_comments;DROP TABLE IF EXISTS activity_events;DROP TABLE IF EXISTS finance_reviews;DROP TABLE IF EXISTS approval_steps;DROP TABLE IF EXISTS receipts;DROP TABLE IF EXISTS expense_items;DROP TABLE IF EXISTS expense_reports;DROP TABLE IF EXISTS expense_policies;DROP TABLE IF EXISTS currencies;DROP TABLE IF EXISTS reporting_lines;DROP TABLE IF EXISTS users;DROP TABLE IF EXISTS departments;DROP TABLE IF EXISTS password_reset_tokens;DROP TABLE IF EXISTS sessions;
PRAGMA foreign_keys=ON;
CREATE TABLE departments(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,department_id INTEGER REFERENCES departments(id),status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE reporting_lines(employee_id INTEGER PRIMARY KEY REFERENCES users(id),manager_id INTEGER NOT NULL REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE password_reset_tokens(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE currencies(code TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE expense_policies(id INTEGER PRIMARY KEY,category TEXT NOT NULL,currency TEXT NOT NULL REFERENCES currencies(code),max_amount_cents INTEGER NOT NULL,receipt_threshold_cents INTEGER NOT NULL,effective_from TEXT NOT NULL,effective_to TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(category,currency,effective_from));
CREATE TABLE expense_reports(id INTEGER PRIMARY KEY,report_number TEXT NOT NULL UNIQUE,employee_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,currency TEXT NOT NULL REFERENCES currencies(code),business_purpose TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',total_cents INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE expense_items(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE,expense_date TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount_cents INTEGER NOT NULL,merchant TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE receipts(id INTEGER PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES expense_items(id) ON DELETE CASCADE,filename TEXT NOT NULL,mime_type TEXT NOT NULL,bytes BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE approval_steps(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES expense_reports(id),manager_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL DEFAULT 'pending',comment TEXT NOT NULL DEFAULT '',decided_at TEXT);
CREATE TABLE finance_reviews(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL UNIQUE REFERENCES expense_reports(id),finance_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL,comment TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE activity_events(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE,actor_id INTEGER REFERENCES users(id),event_type TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE report_comments(id INTEGER PRIMARY KEY,report_id INTEGER NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE,author_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,message TEXT NOT NULL,report_id INTEGER REFERENCES expense_reports(id),read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE reimbursement_batches(id INTEGER PRIMARY KEY,batch_number TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'created',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,processed_at TEXT,idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE batch_items(batch_id INTEGER NOT NULL REFERENCES reimbursement_batches(id),report_id INTEGER NOT NULL UNIQUE REFERENCES expense_reports(id),amount_cents INTEGER NOT NULL,PRIMARY KEY(batch_id,report_id));
